(function mergeBg3LootTables(){
  if(!window.DND_LOOT_TABLES) window.DND_LOOT_TABLES={Common:[],Uncommon:[],Rare:[],'Very Rare':[],Legendary:[]};
  for(const [rarity,items] of Object.entries(window.DND_BG3_LOOT_ITEMS||{})){
    window.DND_LOOT_TABLES[rarity]=window.DND_LOOT_TABLES[rarity]||[];
    const seen=new Set(window.DND_LOOT_TABLES[rarity].map(item=>`${item.name}::${item.source||''}`));
    for(const item of items){
      const key=`${item.name}::${item.source||''}`;
      if(!seen.has(key)){ window.DND_LOOT_TABLES[rarity].push(item); seen.add(key); }
    }
  }
})();
